
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_relpbe0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_relpbe0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.272243412151440e+00, -3.207439328487504e+00, -3.116625669381720e+00, -2.990812450698325e+00, -2.819353699544799e+00, -2.591131434523488e+00, -2.297421888678444e+00, -1.937241279402794e+00, -1.525427641162287e+00, -1.102004588685403e+00, -7.377361483383643e-01, -5.498572487178941e-01, -4.852951204726642e-01, -3.911704750616826e-01, -2.725653054931608e-01, -1.637574822073018e-01, -8.860832970136730e-02, -4.022896730961975e-02, -9.706630551890874e-03, -1.112785033092702e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


